 [$reader,$d,$g]=shStart('POC-02',102);$lab->q($d,'UPDATE probe SET n=1 WHERE id=102');$before=$lab->value($reader,102);$ok=$g->checkpoint($d);$lab->q($d,'ROLLBACK');$after=$lab->value($reader,102);$lab->require($before===0 && $after===0 && $ok,'Own transaction endpoint failed');shResult('POC-02','Marker validity and independent visibility across own BEGIN/DML/ROLLBACK',array('checkpoint_accepted'=>$ok,'reader_before'=>$before,'reader_after_rollback'=>$after),'Actual SQL transaction exercised; marker acceptance is not unique physical transaction identity');$lab->close($d);$lab->close($reader);
