 [$reader,$d,$g]=shStart('POC-06-rotation-gap',132);$lab->q($d,'UPDATE probe SET n=1 WHERE id=132');$ok=$g->checkpoint($d,static function()use($lab,$d){$lab->q($d,'COMMIT','fault');$lab->q($d,'BEGIN','fault');});$again=$g->checkpoint($d);$n=$lab->value($reader,132);$lab->require($ok&&$again&&$n===1,'Rotation-gap measurement changed');shResult($lab->case,'Inject same-connection COMMIT/BEGIN between release and re-creation (no nonce knowledge)',array('first_accepted'=>$ok,'next_accepted'=>$again,'early_committed_n'=>$n),'COUNTEREXAMPLE under inter-call SQL injection: destructive marker renewal has a blind interval; requires stronger serialization assumption than existing event checks');$lab->close($d);$lab->close($reader);
