 [$reader,$d,$g]=shStart('POC-08-model',150);$lab->q($d,'ROLLBACK');$m=new ShDepthModel($lab,$d);$g=new ShMarkerHypothesis($lab,$d);$lab->require($g->prepare(),'Prepare nested model failed');$m->begin();$lab->require($g->beginEvidence($m->depth),'Outer marker failed');$m->begin();$m->commit();$lab->q($d,'UPDATE probe SET n=1 WHERE id=150','counter-model');$m->begin();$m->rollback();$accepted=$g->checkpoint($d);$visible=$lab->value($reader,150);$m->rollback();$lab->require($accepted&&$visible===0&&$lab->value($reader,150)===0,'Depth model failed');shResult($lab->case,'Nested counter calls issue only one physical outer BEGIN/ROLLBACK; inner rollback does not roll back SQL',array('checkpoint'=>$accepted,'depth_after_outer_rollback'=>$m->depth,'independent_n'=>0),'Source-compatible MODEL plus real MySQL; NOT actual loaded Dolibarr Core integration');$lab->close($d);$lab->close($reader);
