 $signatures=array();foreach(array('COMMIT','ROLLBACK')as$i=>$request){foreach(array('normal','premature-opposite')as$j=>$fault){[$reader,$d,$g]=shStart('POC-10-'.$request.'-'.$fault,170+$i*2+$j);$id=170+$i*2+$j;$lab->q($d,'UPDATE probe SET n=1 WHERE id='.$id);$lab->require($g->checkpoint($d),'Pre-end checkpoint failed');if($j)$lab->q($d,$request==='COMMIT'?'ROLLBACK':'COMMIT','fault');$ack=$lab->q($d,$request)['ack'];$missing=null;try{$lab->q($d,'RELEASE SAVEPOINT '.$g->markerForFaultOnly(),'hypothesis');}catch(mysqli_sql_exception $e){$missing=$e->getCode();}$sig=array('ack'=>$ack,'marker_error'=>$missing,'ac'=>$lab->meta($d)['ac']);$signatures[$request][$fault]=$sig;$n=$lab->value($reader,$id);$end=$g->completion($request,$ack);$lab->require($missing===1305&&$end==='UNKNOWN/STOP'&&$n===($request==='COMMIT'?($j?0:1):($j?1:0)),'Completion ambiguity measurement failed');shResult($lab->case,'Compare acknowledged completion/no-op after premature opposite completion',array('signature'=>$sig,'independent_n'=>$n,'guard_result'=>$end),'UNPROVEN completion: same chosen endpoint evidence, different data outcome; refuse confirmation without exact-ended-event proof');$lab->close($d);$lab->close($reader);}}
